using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable or AI:ApiKey in configuration.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddSingleton<NoteService>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    """
    You are a research agent. Your job is to research a topic by searching the web,
    taking notes on important findings, and then providing a comprehensive summary.

    Workflow:
    1. Search the web for information on the given topic using multiple queries.
    2. Take notes on key findings from each search.
    3. After gathering enough information, provide a final summary of your research.

    Always take notes before summarizing so you can reference your findings.
    """);

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "recent advances in quantum computing 2026";

Console.WriteLine($"🔍 Researching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    Tools = [.. AIFunctionFactory.Create(researchTools)],
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    }
};

await foreach (var message in agent.InvokeStreamingAsync(messages, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n📝 Notes taken during research:");
var noteService = host.Services.GetRequiredService<NoteService>();
foreach (var note in noteService.GetAllNotes())
{
    Console.WriteLine($"  • {note}");
}

// --- Services and Tools ---

public sealed class NoteService
{
    private readonly List<string> _notes = [];

    public void AddNote(string note) => _notes.Add(note);

    public IReadOnlyList<string> GetAllNotes() => _notes.AsReadOnly();
}

public sealed class ResearchTools(NoteService noteService)
{
    private static readonly HttpClient Http = new();

    [Description("Search the web for information on a query. Returns relevant search result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";

            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

            var response = await Http.SendAsync(request, cancellationToken);
            var html = await response.Content.ReadAsStringAsync(cancellationToken);

            var snippets = ExtractSnippets(html);
            return snippets.Length > 0
                ? snippets
                : $"Search completed for '{query}'. No detailed snippets available, but the search was performed successfully.";
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note. Use this to record key findings from searches.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        noteService.AddNote(note);
        Console.WriteLine($"  📝 Note saved: \"{Truncate(note, 80)}\"");
        return $"Note saved successfully. Total notes: {noteService.GetAllNotes().Count}";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        var notes = noteService.GetAllNotes();
        if (notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n", notes.Select((n, i) => $"{i + 1}. {n}"));
    }

    private static string ExtractSnippets(string html)
    {
        var results = new List<string>();
        var snippetMarker = "result__snippet";
        var index = 0;

        while (results.Count < 5 && (index = html.IndexOf(snippetMarker, index, StringComparison.Ordinal)) >= 0)
        {
            var start = html.IndexOf('>', index) + 1;
            if (start <= 0) break;

            var end = html.IndexOf('<', start);
            if (end <= start) { index = start; continue; }

            var snippet = html[start..end].Trim();
            snippet = System.Net.WebUtility.HtmlDecode(snippet);

            if (snippet.Length > 20)
                results.Add(snippet);

            index = end;
        }

        return string.Join("\n\n", results);
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "...";
}

